	s := providerNative(t)
	fresh := providerNative(t)
	repo := providerRepository{s}
	other := providerRepository{fresh}
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	release, err := repo.Serialize(ctx)
	if err != nil {
		t.Fatal(err)
	}
	var once sync.Once
	finish := func() { once.Do(release) }
	defer finish()
	arrived := make(chan error, 1)
	go func() {
		unlock, err := other.Serialize(ctx)
		if err == nil {
			unlock()
		}
		arrived <- err
	}()
	select {
	case err := <-arrived:
		t.Fatal("another process entered held lease", err)
	case <-time.After(30 * time.Millisecond):
	}
	finish()
	if err := <-arrived; err != nil {
		t.Fatal("waiter did not recover", err)
	}
}", "independent_literal_expectations": "All exact independently authored assertions in the fixture must pass; failures and forbidden effects are asserted explicitly."}

